package com.aitrading.market;

import static org.assertj.core.api.Assertions.*;
import java.math.BigDecimal;
import java.time.Instant;
import org.junit.jupiter.api.Test;

class RealtimeTimeframeAggregatorTests {
    @Test void updatesAllSevenUtcBucketsFromEveryQuote(){var aggregator=new RealtimeTimeframeAggregator();var result=aggregator.accept(q("1","2026-09-10T10:23:25Z","100","102"));assertThat(result.price()).isEqualByComparingTo("101");assertThat(result.current()).containsOnlyKeys("1m","5m","15m","30m","1h","4h","1d");assertThat(result.current().get("1m").time()).isEqualTo(Instant.parse("2026-09-10T10:23:00Z"));assertThat(result.current().get("5m").time()).isEqualTo(Instant.parse("2026-09-10T10:20:00Z"));assertThat(result.current().get("15m").time()).isEqualTo(Instant.parse("2026-09-10T10:15:00Z"));assertThat(result.current().get("30m").time()).isEqualTo(Instant.parse("2026-09-10T10:00:00Z"));assertThat(result.current().get("1h").time()).isEqualTo(Instant.parse("2026-09-10T10:00:00Z"));assertThat(result.current().get("4h").time()).isEqualTo(Instant.parse("2026-09-10T08:00:00Z"));assertThat(result.current().get("1d").time()).isEqualTo(Instant.parse("2026-09-10T00:00:00Z"));}
    @Test void preservesOpenUpdatesHighLowCloseAndFinalizesOnlyM1AtRollover(){var aggregator=new RealtimeTimeframeAggregator();aggregator.accept(q("1","2026-09-10T03:59:10Z","99","101"));var same=aggregator.accept(q("2","2026-09-10T03:59:50Z","103","105"));var candle=same.current().get("4h");assertThat(candle.open()).isEqualByComparingTo("100");assertThat(candle.high()).isEqualByComparingTo("104");assertThat(candle.low()).isEqualByComparingTo("100");assertThat(candle.close()).isEqualByComparingTo("104");var next=aggregator.accept(q("3","2026-09-10T04:00:00Z","101","103"));assertThat(next.finalizedM1().time()).isEqualTo(Instant.parse("2026-09-10T03:59:00Z"));assertThat(next.current().get("4h").time()).isEqualTo(Instant.parse("2026-09-10T04:00:00Z"));}
    @Test void rejectsDuplicateAndOutOfOrderWithoutCreatingGapCandles(){var aggregator=new RealtimeTimeframeAggregator();assertThat(aggregator.accept(q("1","2026-09-09T23:59:00Z","10","12")).accepted()).isTrue();assertThat(aggregator.accept(q("1","2026-09-09T23:59:00Z","10","12")).accepted()).isFalse();assertThat(aggregator.accept(q("2","2026-09-09T23:58:59Z","9","11")).accepted()).isFalse();var next=aggregator.accept(q("3","2026-09-10T00:05:00Z","12","14"));assertThat(next.current().get("1m").time()).isEqualTo(Instant.parse("2026-09-10T00:05:00Z"));assertThat(next.current().get("1d").time()).isEqualTo(Instant.parse("2026-09-10T00:00:00Z"));}
    @Test void secondQuoteInsideSameMinuteImmediatelyChangesEveryTimeframeWithoutFinalizing(){var aggregator=new RealtimeTimeframeAggregator();var first=aggregator.accept(q("1","2026-09-10T10:23:10Z","100","102"));var second=aggregator.accept(q("2","2026-09-10T10:23:20Z","104","106"));assertThat(second.finalizedM1()).isNull();for(String timeframe:RealtimeTimeframeAggregator.TIMEFRAMES){assertThat(second.current().get(timeframe).time()).isEqualTo(first.current().get(timeframe).time());assertThat(second.current().get(timeframe).open()).isEqualByComparingTo("101");assertThat(second.current().get(timeframe).close()).isEqualByComparingTo("105");assertThat(second.current().get(timeframe).high()).isEqualByComparingTo("105");}}
    private static RealtimeTimeframeAggregator.Quote q(String id,String time,String bid,String offer){return new RealtimeTimeframeAggregator.Quote(id,Instant.parse(time),new BigDecimal(bid),new BigDecimal(offer));}
}
